// Check for stale participants (no presence heartbeat in last 3 minutes)
// Longer timeout than arena since debates can have longer pauses

const staleParticipants = [];
const now = new Date();
const THREE_MINUTES = 3 * 60 * 1000;

for (const participant of $input.all()[0].json.documents) {
  const lastActiveAt = participant.lastActiveAt ? new Date(participant.lastActiveAt) : null;
  const timeSinceLastActive = lastActiveAt ? now - lastActiveAt : Infinity;

  // Mark as stale if:
  // 1. No lastActiveAt (never sent heartbeat)
  // 2. lastActiveAt > 3 minutes ago
  if (!lastActiveAt || timeSinceLastActive > THREE_MINUTES) {
    staleParticipants.push({
      documentId: participant.$id,
      userId: participant.userId,
      roomId: participant.roomId,
      role: participant.role,
      lastActiveAt: participant.lastActiveAt || 'never',
      staleDuration: lastActiveAt ? Math.floor(timeSinceLastActive / 1000) + 's' : 'never'
    });
  }
}

console.log(`Found ${staleParticipants.length} stale debate/discussion participants out of ${$input.all()[0].json.documents.length} total`);

return staleParticipants.map(p => ({ json: p }));

// Log cleanup action
const participant = $input.all()[0].json;

console.log(`🧹 CLEANUP: Removed stale debate/discussion participant`);
console.log(`  User ID: ${participant.userId}`);
console.log(`  Room ID: ${participant.roomId}`);
console.log(`  Role: ${participant.role}`);
console.log(`  Last Active: ${participant.lastActiveAt}`);
console.log(`  Stale Duration: ${participant.staleDuration}`);

return [{ json: participant }];

// Summary of cleanup operation
const cleanedCount = $input.all().length;

console.log(`✅ Debate/Discussion participant cleanup complete`);
console.log(`   Removed ${cleanedCount} stale participants`);

return [{ json: { cleanedCount, timestamp: new Date().toISOString() } }];
